import{z as B,x as o,o as l,c as C,q as s,j as i,D as e,d as r,s as A,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"5G 切片与 URLLC","description":"","frontmatter":{"title":"5G 切片与 URLLC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/5g-slicing.md","filePath":"cs/5g-slicing.md","lastUpdated":1791413859000}'),p={name:"cs/5g-slicing.md"};function L(d,a,c,D,R,m){const t=o("Mermaid");return l(),C("div",null,[a[2]||(a[2]=s('<h1 id="_5g-切片与-urllc" tabindex="-1">5G 切片与 URLLC <a class="header-anchor" href="#_5g-切片与-urllc" aria-label="Permalink to &quot;5G 切片与 URLLC&quot;">​</a></h1><div class="epigraph"><p>切片把同一物理 RAN/核心切成隔离的逻辑网络；URLLC 用短时隙与高可靠编码换毫秒级空口，牺牲频谱效率。</p><footer>—— 据 3GPP TS 23.501 切片；TS 22.261 与 38 系列 URLLC 相关条款整理</footer></div><p><a href="/cs/cellular-ran-core">上一课</a> 给出 RAN 与核心。eMBB 大带宽与工厂控制不能共用同一张「尽力而为」承载。缺口是<strong>切片</strong>与 <strong>URLLC</strong>：NSI 隔离资源；URLLC 要 \\(10^{-5}\\) 量级空口可靠与毫秒延迟。本课不把卫星轨道写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DiffServ 后课给 IP hop 着色；切片更强：独立的控制面与用户面实例、SLA、可能独立的 UPF。URLLC：迷你时隙、免授权上行、重复传输，工作点远离香农极限换延迟——与 Wi‑Fi OFDMA 调度同类但有牌照与更硬的时间槽。不是 PFC：空口不能「暂停邻站一整口」来保证工厂周期。</p><p>不要把切片写成 VLAN：隔离在核心与 RAN 资源上，不止 802.1Q 标签。</p><p><span class="marginnote">常见误区：初学者容易把切片想成「给流量打个 VLAN 标签就完事」。实际上切片是把一块无线频谱资源加一组核心网功能（如独立的 UPF）整块划给一类业务——eMBB 用户再拥挤，也不该挤占 URLLC 切片预留的资源。</span></p><p><span class="marginnote">术语翻译：URLLC（超可靠低时延通信）就是用「更短的时隙 + 同一包多发几遍」的手段，来做「把空口丢包率压到十万分之一量级、延迟压到毫秒级」这件事。代价是频谱效率：同样的无线电资源能装下的普通数据变少了。</span></p><p><span class="marginnote">eMBB / URLLC / mMTC 是 5G 三类场景。实现参差，本课钉合同：隔离与时延可靠指标，不点名某运营商套餐。</span></p><h3 id="切片强于-dscp" tabindex="-1">切片强于 DSCP <a class="header-anchor" href="#切片强于-dscp" aria-label="Permalink to &quot;切片强于 DSCP&quot;">​</a></h3><p>隔离的是实例与资源，不只 hop 着色。URLLC 用效率换尾延迟，工作点远离容量极限。实验室演示不等于全国 SLA。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：物理网 → 切片实例 → 不同 SLA。URLLC 路径：短 TTI → 编码重复 → 核心低时延转发。对照以太网 PFC：一跳反压 vs 端到端时延预算。</p>',13)),(l(),i(n,null,{default:e(()=>[A(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PHY%5B%22%E7%89%A9%E7%90%86%20RAN%2F%E6%A0%B8%E5%BF%83%22%5D%20--%3E%20SL%5B%22%E5%88%87%E7%89%87%E5%AE%9E%E4%BE%8B%22%5D%0A%20%20SL%20--%3E%20EMBB%5B%22eMBB%20%E5%AE%B9%E9%87%8F%22%5D%0A%20%20SL%20--%3E%20URL%5B%22URLLC%20%E6%97%B6%E5%BB%B6%22%5D%0A%20%20URL%20--%3E%20SHORT%5B%22%E7%9F%AD%E6%97%B6%E9%9A%99%E4%B8%8E%E9%87%8D%E5%A4%8D%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"容量 \\(C\\) 被切片划分：给 URLLC 的资源不能同时给 eMBB 满载。这是显式资源预留，与互联网核心的统计复用对照。移动性仍走核心锚，切片要跟着会话走。主干端到端：再可靠的空口也不替代应用校验。",-1)),a[5]||(a[5]=E("p",null,"与 Wi‑Fi 6 调度：都是时频资源分配；5G 有许可频谱与更硬的同步。",-1)),a[6]||(a[6]=E("p",null,"第一张图画的是「切片把物理网拆成几个 SLA 不同的逻辑网」；这里补上第二个问题：URLLC 单个包靠什么把丢包率压到 \\(10^{-5}\\) 量级——答案是短时隙调度加多副本传输，接收方任一副本成功即可交付。",-1)),(l(),i(n,null,{default:e(()=>[A(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%B7%A5%E5%8E%82%E6%8E%A7%E5%88%B6%E5%8C%85%22%5D%20--%3E%20SCHED%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%EF%BC%9A%E8%BF%B7%E4%BD%A0%E6%97%B6%E9%9A%99%22%5D%0A%20%20SCHED%20--%3E%20C1%5B%22%E5%89%AF%E6%9C%AC%201%EF%BC%9A%E9%A2%91%E6%AE%B5%20A%22%5D%0A%20%20SCHED%20--%3E%20C2%5B%22%E5%89%AF%E6%9C%AC%202%EF%BC%9A%E9%A2%91%E6%AE%B5%20B%22%5D%0A%20%20C1%20--%3E%20RX%5B%22%E6%8E%A5%E6%94%B6%E6%9C%BA%E5%88%86%E5%88%AB%E8%A7%A3%E7%A0%81%22%5D%0A%20%20C2%20--%3E%20RX%0A%20%20RX%20--%3E%20OK%7B%22%E4%BB%BB%E4%B8%80%E5%89%AF%E6%9C%AC%E6%88%90%E5%8A%9F%EF%BC%9F%22%7D%0A%20%20OK%20--%3E%7C%22%E6%98%AF%22%7C%20DELIVER%5B%22%E6%8C%89%E6%97%B6%E9%9A%99%E8%BE%B9%E7%95%8C%E4%BA%A4%E4%BB%98%22%5D%0A%20%20OK%20--%3E%7C%22%E5%90%A6%22%7C%20DROP%5B%22%E6%9C%AC%E6%97%B6%E9%9A%99%E4%B8%A2%E5%BC%83%EF%BC%8C%E9%9D%A0%E4%B8%8A%E5%B1%82%E5%85%9C%E5%BA%95%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">数字实例：普通 5G 一个时隙约 0.5 毫秒（30 kHz 子载波下含 14 个符号），迷你时隙可以只占 2 个或 7 个符号，也就是零点零七到零点二五毫秒就能发一次——「短 TTI」省的就是这段时间。再叠加两个副本走不同频段，单个副本丢 \\(10^{-2}\\) 量级时，两个独立副本同时失败的概率就压到了 \\(10^{-4}\\) 量级——要把可靠性推到 \\(10^{-5}\\)，还得单副本丢包更低或叠加更多副本。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入网络开放 API 的全部 NEF。卫星与高延迟链路是下一课。后课默认：切片 = 隔离逻辑网；URLLC = 用效率换尾延迟。</p><p>实验室演示不等于全国覆盖的 URLLC SLA。</p><p>下一课<a href="/cs/satellite-latency">卫星与高延迟链路</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>切片隔离 SLA，强于单跳 DSCP。</li><li>URLLC 短时隙、重复、远离容量极限。</li><li>资源预留与互联网统计复用对照。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：3GPP TS 23.501、22.261。</li></ul>',7))])}const u=B(p,[["render",L]]);export{S as __pageData,u as default};
